CREATE TABLE code_inspections(inspection_id BIGINT, case_number VARCHAR, case_type VARCHAR, case_group VARCHAR, inspection VARCHAR, result VARCHAR, scheduled DATE, completed DATE, address VARCHAR, parcel_id VARCHAR, lat DOUBLE, lon DOUBLE);;
CREATE TABLE contamination(site VARCHAR, address VARCHAR, city VARCHAR, county VARCHAR, parcel_id VARCHAR, status VARCHAR, kind VARCHAR, activity VARCHAR, programs VARCHAR, tanks BOOLEAN, cleanup BOOLEAN, institutional_controls BOOLEAN, industry VARCHAR, parcel_city VARCHAR, lat DOUBLE, lon DOUBLE);;
CREATE TABLE food_inspections(facility_id VARCHAR, business VARCHAR, category VARCHAR, risk_level VARCHAR, address VARCHAR, inspection_id BIGINT, inspection_type VARCHAR, inspection_date DATE, score BIGINT, violation_id HUGEINT, violation_priority VARCHAR, violation_points BIGINT, food_code_item VARCHAR, parcel_id VARCHAR, neighborhood VARCHAR, lat DOUBLE, lon DOUBLE);;
CREATE TABLE licences(business VARCHAR, "type" VARCHAR, category VARCHAR, address VARCHAR, city VARCHAR, status VARCHAR, expires DATE, licensed_since DATE, "source" VARCHAR);;
CREATE TABLE meta("snapshot" VARCHAR, "source" VARCHAR);;
CREATE TABLE parcels(parcel_id VARCHAR, address VARCHAR, city VARCHAR, county VARCHAR, "use" VARCHAR, year_built BIGINT, assessed BIGINT, lot_sqft BIGINT, building_sqft BIGINT, stories BIGINT, last_sale_price BIGINT, last_sale_month VARCHAR, lat DOUBLE, lon DOUBLE);;
CREATE TABLE permits(permit_no VARCHAR, issued DATE, completed DATE, city VARCHAR, kind VARCHAR, "work" VARCHAR, trade VARCHAR, occupancy VARCHAR, status VARCHAR, value_usd BIGINT, fees_usd BIGINT, units_added BIGINT, units_removed BIGINT, rows_per_permit BIGINT, parcel_id VARCHAR, lat DOUBLE, lon DOUBLE);;
CREATE TABLE sales(parcel_id VARCHAR, address VARCHAR, county VARCHAR, sale_month VARCHAR, price BIGINT, assessed BIGINT, "use" VARCHAR, year_built BIGINT, "owner" VARCHAR, owner_type VARCHAR, arms_length BOOLEAN, multi_parcel_deed BOOLEAN, usable_comp BOOLEAN, parcel_city VARCHAR, lat DOUBLE, lon DOUBLE);;

